from pathlib import Path
import json,hashlib,copy,math,shutil,bisect
P=Path(__file__).resolve().parent;prior=P.parent/'articulated-sprites-v54';source=P/'source/retargeted-endpoints.json';D=json.loads(source.read_text());out=P/'inputs';out.mkdir(exist_ok=True)
for n in ['sprite-mesh-player.js','sprite-articulated-player.js','sprite-segmented-player.js','sprite-clip-clock.cjs']:shutil.copyfile(P.parents[2]/'tools'/n,out/n)
