def interpolate(a,b,t):return [a[j]*(1-t)+b[j]*t for j in [0,1]]
def projection(frames,phase,view):
 f=phase*256;j=min(255,int(f));t=f-j;a=frames[j]['projected'][view];b=frames[j+1]['projected'][view];return {n:{edge:interpolate(a[n][edge],b[n][edge],t) for edge in ['head','tail']} for n in a}
for view in ['S','W','N','E']:
 data=json.loads((prior/('walk-rig-contract.json' if view=='W' else view+'-walk-rig-contract.json')).read_text());defs=data['definitions'];folder=out/'parts'/view;folder.mkdir(parents=True,exist_ok=True)
 for name,a in defs.items():
  src=prior/a['texture'];dest=folder/(name+'.png');shutil.copyfile(src,dest);a['texture']=str(dest.relative_to(P));a['texture_sha256']=hashlib.sha256(dest.read_bytes()).hexdigest()
  if a['kind']=='chain':
   knee=a['rest'][a['nodes'][1]][1];wrist=a['rest'][a['nodes'][2]][1];shoe=a['bands'][3];a['bands']=[knee-16,knee-8,shoe-8,shoe] if a['role']=='leg' else [knee-12,knee-4,wrist-6,wrist+3]
 defs['body'].update(kind='body',influences=[],rest=rest_body[view]);defs['head']['pivot_neck']=rest_body[view]['neck'];neutral=D['neutral_projection'][view];gain=data['source_projection_gain'];channels={'hips':('torso','head'),'neck':('torso','tail'),'head':('head','head')}
 for side in ['left','right']:
  for label,bone,edge in [('hip','thigh','head'),('knee','shin','head'),('ankle','foot','head'),('toe','foot','tail'),('shoulder','upperarm','head'),('elbow','forearm','head'),('wrist','hand','head'),('palm','hand','tail')]:channels[side+'.'+label]=(side+'.'+bone,edge)
 def pose(q):
  p={n:[(q[b][e][j]-neutral[b][e][j])*gain for j in [0,1]] for n,(b,e) in channels.items()};a=q['head']['head'];b=q['head']['tail'];c=neutral['head']['head'];z=neutral['head']['tail'];angle=math.atan2(b[1]-a[1],b[0]-a[0])-math.atan2(z[1]-c[1],z[0]-c[0]);p['head_angle']=[math.atan2(math.sin(angle),math.cos(angle)),0];p['cape_wave']=[0,0];return p
 guard=pose(projection(D['clips']['ready']['frames'],0,view))
 for action,count in [('ready',24),('attack1',16)]:
  original=D['clips'][action];phases=[i/count for i in range(count)] if action=='ready' else [i/(count-1) for i in range(count)];poses=[pose(projection(original['frames'],t,view)) for t in phases]
  if action=='attack1':poses[0]=copy.deepcopy(guard);poses[-1]=copy.deepcopy(guard)
  boundaries=[round(i*original['duration_ms']/count/10)*10 for i in range(count+1)];d={'view':view,'action':action,'canvas':[512,576],'definitions':defs,'order':(['right_leg','left_leg','right_arm','body','head','left_arm'] if view=='W' else ['left_leg','right_leg','left_arm','body','head','right_arm'] if view=='E' else ['left_leg','right_leg','left_arm','right_arm','body','head'] if view=='N' else ['left_leg','right_leg','body','head','left_arm','right_arm']),'poses':poses,'durations_ms':[b-a for a,b in zip(boundaries,boundaries[1:])],'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'source_gain':gain,'source_phases':phases,'scope':'Fixed original rest assets, fresh saved in-place CC0-adapted3D joints, static authored2Drest binding and source head angle around neck. Not new native drawings, exact recovered painted anatomy, original external lunge replay or game integration.','production_pass':False};clips.append(d)
bank={'clips':clips,'production_pass':False};(P/'fight-rig-contract.json').write_text(json.dumps(bank,separators=(',',':'))+'\n')
html='''<!doctype html><html lang="th"><meta charset="utf-8"><style>body{background:#20252d;color:white;font:16px system-ui;margin:20px}canvas{background:#292b30;max-height:75vh}select,button,input{font:inherit;margin:6px}</style><h1>ท่าเตรียมสู้ / หมัดพื้นฐาน · ตรวจต้นแบบ</h1><select id="clip"></select><button id="play" disabled>เล่น / หยุด</button><select id="speed"><option value="1">1×</option><option value="0.25">¼×</option></select><label><input id="loop" type="checkbox" checked>วน</label><div><canvas id="c" width="512" height="576"></canvas></div><input id="frame" type="range" min="0" value="0" disabled><p id="status">กำลังโหลด…</p><script src="inputs/sprite-mesh-player.js"></script><script src="inputs/sprite-articulated-player.js"></script><script src="inputs/sprite-segmented-player.js"></script><script src="inputs/sprite-clip-clock.cjs"></script><script>const D=__DATA__,$=id=>document.getElementById(id),ctx=$('c').getContext('2d'),images=new Map(),layers=new Map();let ci=0,clock,last=null;D.clips.forEach((d,i)=>$('clip').add(new Option(d.action+' · '+d.view,i)));function draw(i){const d=D.clips[ci],p=d.poses[i];ctx.clearRect(0,0,512,576);for(const n of d.order){const m=layers.get(n);if(m instanceof SpriteSegmentedChain)ctx.drawImage(m.drawPieces(p).canvas,0,0);else{m.draw(p);ctx.drawImage(m.canvas,0,0)}}$('frame').value=i;$('status').textContent=d.action+' '+d.view+' · '+(i+1)+'/'+d.poses.length}function choose(i){for(const m of layers.values()){m.dispose();m.gl.getExtension("WEBGL_lose_context")?.loseContext()}layers.clear();ci=i;const d=D.clips[i];for(const[n,a]of Object.entries(d.definitions)){const K=a.kind==='chain'?SpriteSegmentedChain:a.kind==='head'?SpritePickupHead:SpritePickupTorso,m=new K(document.createElement('canvas'),images.get(a.texture),a);m.setViewport(512,576);layers.set(n,m)}clock=new SpriteClipClock({durations:d.durations_ms,loop:$('loop').checked});$('frame').max=d.poses.length-1;draw(0);last=null}function select(i){clock.cancel();clock.seek(D.clips[ci].durations_ms.slice(0,i).reduce((a,b)=>a+b,0));draw(i)}$('clip').onchange=()=>choose(+$('clip').value);$('frame').oninput=()=>select(+$('frame').value);$('loop').onchange=()=>clock.clip.loop=$('loop').checked;$('play').onclick=()=>{if(clock.running)clock.cancel();else if(clock.finished||clock.time===0)clock.start();else clock.running=true;last=null};function tick(now){if(clock?.running)draw(clock.advance((last===null?0:Math.max(0,now-last))*+$('speed').value).frame);last=now;requestAnimationFrame(tick)}Promise.all([...new Set(D.clips.flatMap(d=>Object.values(d.definitions).map(a=>a.texture)))].map(f=>new Promise((ok,no)=>{const im=new Image;im.onload=()=>{images.set(f,im);ok()};im.onerror=()=>no(Error('Missing '+f));im.src=f}))).then(()=>{choose(0);window.READY=true;$('play').disabled=$('frame').disabled=false;requestAnimationFrame(tick)}).catch(e=>{window.LOAD_ERROR=e.message;$('status').textContent=e.message});window.study={data:D,layers,choose,select,draw,get clock(){return clock},get index(){return ci},frame(i){draw(i);return $('c').toDataURL()}};</script></html>''';(P/'fight-review.html').write_text(html.replace('__DATA__',json.dumps(bank,separators=(',',':'))));print('Fight candidate rigs',len(clips))
